SELECT ListPrice * 0.9 AS DiscountedPrice
FROM Production.Product
WHERE DiscountedPrice < 50;

SELECT Name, Color, ListPrice
FROM Production.Product
WHERE Color = 'Red' OR Color = 'Blue' AND ListPrice > 500;

SELECT p.Name, c.Name
FROM Production.Product AS p
CROSS JOIN Production.ProductCategory AS c;

SELECT Name, Color, AVG(ListPrice) AS AveragePrice
FROM Production.Product
GROUP BY Color;

SELECT Color FROM Production.Product WHERE Color IS NOT NULL
UNION
SELECT Color FROM Production.Product WHERE Color IS NOT NULL;

